	'kd9c04680' => '(03) Caractéristiques',
	'kd9c22e93' => 'Susugi Wash &nbsp;/&nbsp; La machine (02) &nbsp;/&nbsp; Quatre chapitres',
	'kda4e7a95' => 'Casiers, assiettes, couverts et plats, dans les mêmes quatre-vingt-dix secondes.',
	'kdb1f19e2' => 'Que faire si la hauteur libre sous plan est inférieure à 830 mm ?',
